/**
 * Build the browser copy of the canonical formula parser.
 * The generated file embeds a sha256 of chemistry-formula-strict.mjs.
 */
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { ATOMIC_WEIGHTS } from '../netlify/lib/chemistry-base.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const strictPath = path.join(root, 'netlify/lib/chemistry-formula-strict.mjs');
const strict = readFileSync(strictPath, 'utf8');
const hash = createHash('sha256').update(strict).digest('hex');
const body = strict
  .replace(/import\s*\{[^}]+\}\s*from\s*'\.\/chemistry-base\.mjs';\s*/, '')
  .replace(/^export /gm, '');

const out = `/* Generated by tools/build-formula-parser.mjs. Do not edit.
 * source-sha256: ${hash}
 */
(function (root) {
  'use strict';
  var ATOMIC_WEIGHTS = ${JSON.stringify(ATOMIC_WEIGHTS)};
  function calcError(message, status, code) {
    var err = new Error(message);
    err.status = status || 400;
    err.code = code || 'invalid_request';
    return err;
  }
${body}
  root.AtomurusFormula = {
    parseFormulaStrict: parseFormulaStrict,
    readFormulaStrict: readFormulaStrict,
    looksIonic: looksIonic,
    formatFormulaDisplay: formatFormulaDisplay,
    ATOMIC_WEIGHTS: ATOMIC_WEIGHTS
  };
  if (typeof module === 'object' && module.exports) module.exports = root.AtomurusFormula;
})(typeof window !== 'undefined' ? window : globalThis);
`;

const destDir = path.join(root, 'assets/chemistry');
mkdirSync(destDir, { recursive: true });
const dest = path.join(destDir, 'formula-parser.js');
writeFileSync(dest, out);
console.log('wrote', path.relative(root, dest), hash.slice(0, 12));
